#!/usr/bin/env python3
# Regenerates benchmarks/data/*.cbor and benchmarks/payloads.h. Run this
# only if you want to change the benchmark payloads themselves -- the
# generated files are committed so `docker build` doesn't need Python.
import struct
import random


def enc_uint(major, n):
    if n < 24:
        return bytes([major << 5 | n])
    elif n < 2**8:
        return bytes([major << 5 | 24, n])
    elif n < 2**16:
        return bytes([major << 5 | 25]) + struct.pack(">H", n)
    elif n < 2**32:
        return bytes([major << 5 | 26]) + struct.pack(">I", n)
    else:
        return bytes([major << 5 | 27]) + struct.pack(">Q", n)


def enc(v):
    if isinstance(v, bool):
        return bytes([0xf5]) if v else bytes([0xf4])
    if v is None:
        return bytes([0xf6])
    if isinstance(v, int):
        return enc_uint(0, v) if v >= 0 else enc_uint(1, -1 - v)
    if isinstance(v, float):
        return bytes([0xfb]) + struct.pack(">d", v)
    if isinstance(v, str):
        b = v.encode()
        return enc_uint(3, len(b)) + b
    if isinstance(v, bytes):
        return enc_uint(2, len(v)) + v
    if isinstance(v, list):
        out = enc_uint(4, len(v))
        for x in v:
            out += enc(x)
        return out
    if isinstance(v, dict):
        out = enc_uint(5, len(v))
        for k, val in v.items():
            out += enc(k) + enc(val)
        return out
    raise TypeError(v)


def main():
    random.seed(42)

    small = enc({"id": 1001, "name": "sensor-07", "active": True, "value": 23.5})

    medium = enc([
        {"id": i, "name": f"sensor-{i:03d}", "active": (i % 3 == 0),
         "value": round(random.uniform(-40, 125), 2),
         "tags": ["a", "b"] if i % 2 == 0 else ["c"]}
        for i in range(200)
    ])

    deep = 1
    for _ in range(30):
        deep = [deep, "x"]
    deep = enc(deep)

    strings = enc([
        f"The quick brown fox jumps over the lazy dog, iteration {i}, lorem ipsum dolor sit amet."
        for i in range(100)
    ])

    payloads = {"small": small, "medium": medium, "deep": deep, "strings": strings}

    for name, data in payloads.items():
        with open(f"data/{name}.cbor", "wb") as f:
            f.write(data)
        print(name, len(data), "bytes")

    lines = [
        "// Auto-generated by benchmarks/gen_payloads.py -- same bytes fed to every library.",
        "#pragma once",
        "#include <cstdint>",
        "#include <cstddef>",
        "",
    ]
    for name, data in payloads.items():
        arr = ",".join(str(b) for b in data)
        lines.append(f"inline constexpr std::uint8_t {name}_bytes[] = {{{arr}}};")
        lines.append(f"inline constexpr std::size_t {name}_len = {len(data)};")
        lines.append("")
    with open("payloads.h", "w") as f:
        f.write("\n".join(lines))
    print("wrote payloads.h")


if __name__ == "__main__":
    main()
